package main

import (
	"bufio"
	"bytes"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64           // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"               // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.Zero // PIC 9(8)V99 len=10 = 0
var WsYear int64 = 0                     // PIC 99 len=2 = 0
var WsCount int64 = 0                    // PIC 99 len=2 = 0
var WsBalEd string                       // PIC ZZ,ZZZ,ZZ9.99 len=13

var CurRec SchedRec
var fileRecords []string
var filePos int

func inputDone() bool {
	return WsEofFlag == "Y"
}

func parseDecimalField(raw string, scale int32) decimal.Decimal {
	if len(raw) == 0 {
		return decimal.Zero
	}
	var b strings.Builder
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if c == ' ' {
			b.WriteByte('0')
		} else if c >= '0' && c <= '9' {
			b.WriteByte(c)
		} else {
			b.WriteByte('0')
		}
	}
	s := b.String()
	if s == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(s)
	if err != nil {
		n, _ := strconv.ParseInt(s, 10, 64)
		d = decimal.NewFromInt(n)
	}
	d = d.Shift(-scale)
	return d
}

func parseIntField(raw string) int64 {
	if len(raw) == 0 {
		return 0
	}
	var b strings.Builder
	for i := 0; i < len(raw); i++ {
		c := raw[i]
		if c == ' ' {
			b.WriteByte('0')
		} else if c >= '0' && c <= '9' {
			b.WriteByte(c)
		} else {
			b.WriteByte('0')
		}
	}
	s := b.String()
	if s == "" {
		return 0
	}
	n, _ := strconv.ParseInt(s, 10, 64)
	return n
}

func roundHalfAway(v decimal.Decimal, scale int32) decimal.Decimal {
	shifted := v.Shift(scale)
	truncated := shifted.Truncate(0)
	remainder := shifted.Sub(truncated)
	half := decimal.NewFromInt(5).Shift(-1) // 0.5
	negHalf := half.Neg()
	if v.Sign() >= 0 {
		if remainder.Cmp(half) >= 0 {
			truncated = truncated.Add(decimal.NewFromInt(1))
		}
	} else {
		if remainder.Cmp(negHalf) <= 0 {
			truncated = truncated.Sub(decimal.NewFromInt(1))
		}
	}
	return truncated.Shift(-scale)
}

func truncateDecimal(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	isNeg := val.Sign() < 0
	vAbs := val.Abs()
	sFixed := vAbs.StringFixed(scale)
	var intPartStr, fracPartStr string
	if scale == 0 {
		intPartStr = sFixed
		if idx := strings.Index(intPartStr, "."); idx >= 0 {
			intPartStr = intPartStr[:idx]
		}
		fracPartStr = ""
	} else {
		parts := strings.Split(sFixed, ".")
		if len(parts) == 2 {
			intPartStr = parts[0]
			fracPartStr = parts[1]
			if len(fracPartStr) < int(scale) {
				fracPartStr += strings.Repeat("0", int(scale)-len(fracPartStr))
			} else if len(fracPartStr) > int(scale) {
				fracPartStr = fracPartStr[:scale]
			}
		} else {
			intPartStr = parts[0]
			fracPartStr = strings.Repeat("0", int(scale))
		}
	}
	combined := intPartStr + fracPartStr
	totalDigits := intDigits + int(scale)
	if len(combined) > totalDigits {
		combined = combined[len(combined)-totalDigits:]
	}
	var newIntStr, newFracStr string
	if scale == 0 {
		newIntStr = combined
		if newIntStr == "" {
			newIntStr = "0"
		}
	} else {
		if len(combined) <= int(scale) {
			newIntStr = "0"
			padLen := int(scale) - len(combined)
			newFracStr = strings.Repeat("0", padLen) + combined
		} else {
			newIntStr = combined[:len(combined)-int(scale)]
			newFracStr = combined[len(combined)-int(scale):]
		}
		if newIntStr == "" {
			newIntStr = "0"
		}
	}
	var recon string
	if scale == 0 {
		recon = newIntStr
	} else {
		recon = newIntStr + "." + newFracStr
	}
	if isNeg {
		isZero := true
		for _, c := range combined {
			if c != '0' {
				isZero = false
				break
			}
		}
		if !isZero {
			recon = "-" + recon
		}
	}
	d, err := decimal.NewFromString(recon)
	if err != nil {
		return val
	}
	return d
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var adj decimal.Decimal
	if rounded {
		adj = roundHalfAway(v, scale)
	} else {
		adj = v.Truncate(scale)
	}
	return truncateDecimal(adj, intDigits, scale)
}

func storeInt(val int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if mod == 0 {
		return val
	}
	if val >= 0 {
		return val % mod
	}
	r := val % mod
	if r < 0 {
		r += mod
	}
	return r
}

func formatUneditedInt(v int64, width int) string {
	v = storeInt(v, width)
	s := strconv.FormatInt(v, 10)
	if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	} else if len(s) > width {
		s = s[len(s)-width:]
	}
	return s
}

func formatBal(v decimal.Decimal) string {
	const picInt = "ZZ,ZZZ,ZZ9"
	const fracDigits = 2
	intCap := 8
	vAbs := v.Abs()
	intPartDec := vAbs.Truncate(0)
	intStr := intPartDec.StringFixed(0)
	if idx := strings.Index(intStr, "."); idx >= 0 {
		intStr = intStr[:idx]
	}
	// overflow truncation for integer part
	if len(intStr) > intCap {
		intStr = intStr[len(intStr)-intCap:]
	}
	paddedInt := strings.Repeat("0", intCap-len(intStr)) + intStr
	picRunes := []rune(picInt)
	paddedRunes := []rune(paddedInt)
	resultInt := make([]rune, len(picRunes))
	dIdx := 0
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			resultInt[i] = paddedRunes[dIdx]
			dIdx++
		} else {
			resultInt[i] = ch
		}
	}
	suppress := true
	for i, ch := range picRunes {
		if ch == 'Z' {
			if suppress && resultInt[i] == '0' {
				resultInt[i] = ' '
			} else {
				suppress = false
			}
		} else if ch == '9' {
			suppress = false
		} else if ch == ',' {
			if suppress {
				resultInt[i] = ' '
			} else {
				resultInt[i] = ','
			}
		}
	}
	sFixed := vAbs.StringFixed(int32(fracDigits))
	var fracStr string
	if fracDigits > 0 {
		idx := strings.Index(sFixed, ".")
		if idx >= 0 {
			fracStr = sFixed[idx+1:]
			if len(fracStr) < fracDigits {
				fracStr += strings.Repeat("0", fracDigits-len(fracStr))
			} else if len(fracStr) > fracDigits {
				fracStr = fracStr[:fracDigits]
			}
		} else {
			fracStr = strings.Repeat("0", fracDigits)
		}
		return string(resultInt) + "." + fracStr
	}
	return string(resultInt)
}

func openSchedFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			fileRecords = []string{}
			filePos = 0
			return
		}
		fmt.Fprintf(os.Stderr, "open error: %v\n", err)
		os.Exit(1)
	}
	fileRecords = []string{}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		line := scanner.Text()
		if len(line) < 16 {
			line = line + strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		fileRecords = append(fileRecords, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read error: %v\n", err)
		os.Exit(1)
	}
	filePos = 0
}

func readPara() {
	if filePos >= len(fileRecords) {
		WsEofFlag = "Y"
		return
	}
	line := fileRecords[filePos]
	filePos++
	CurRec.ScAcct = line[0:4]
	rawPrin := line[4:11]
	CurRec.ScPrin = parseDecimalField(rawPrin, 2)
	rawRate := line[11:15]
	CurRec.ScRate = parseDecimalField(rawRate, 2)
	rawYears := line[15:16]
	CurRec.ScYears = parseIntField(rawYears)
}

func processPara() {
	WsBal = storeDecimal(CurRec.ScPrin, 8, 2, false)
	WsYear = storeInt(1, 2)
	for WsYear <= CurRec.ScYears {
		rateDiv100 := CurRec.ScRate.Shift(-2)
		factor := decimal.NewFromInt(1).Add(rateDiv100)
		computed := WsBal.Mul(factor)
		WsBal = storeDecimal(computed, 8, 2, true)
		WsBalEd = formatBal(WsBal)
		yearStr := formatUneditedInt(WsYear, 2)
		line := CurRec.ScAcct + " Y" + yearStr + " " + WsBalEd
		fmt.Println(line)
		WsYear = storeInt(WsYear+1, 2)
	}
	WsBalEd = formatBal(WsBal)
	finalLine := CurRec.ScAcct + " FINAL " + WsBalEd
	fmt.Println(finalLine)
	WsCount = storeInt(WsCount+1, 2)
	readPara()
}

func mainPara() {
	openSchedFile()
	readPara()
	for !inputDone() {
		processPara()
	}
	countStr := formatUneditedInt(WsCount, 2)
	fmt.Printf("SCHEDULES: %s\n", countStr)
}

func main() {
	mainPara()
}
